UPDATE companies SET description='Bharat Forge Aluminum USA, Inc. was founded in 2020 and operates a state-of-the-art plant in Sanford, North Carolina.

The facility produces lightweight aluminum parts as well as steel components, serving automotive and industrial markets. While specific processes are not detailed publicly, the company emphasizes manufacturing high-quality parts for trucks, cars, and off-highway equipment, with a Marine Class Approval of Manufacturer underscoring its capability for safety-critical applications.

Bharat Forge Aluminum USA highlights a lowest-total-cost-of-ownership proposition and a sustainability commitment, noting it is reducing its carbon footprint even as it expands. The company has announced aggressive growth targets, aiming to double output in two years and triple it in five, while investing in community partnerships and workforce development through an NC State internship program and local school initiatives.', certifications=ARRAY['ISO 14001','Marine Class Approval of Manufacturer']::text[], profile='{"capabilities": ["Lightweight aluminum parts manufacturing", "Steel parts manufacturing"], "industries": ["Trucks", "Cars", "Off-highway", "Marine", "Industrial"], "materials": ["Aluminum", "Steel"], "equipment": [], "volume": "", "lead_time": "", "tolerances": "", "built_on": ["Lowest Total Cost of Ownership (TCO) proposition", "Reducing carbon footprint while expanding production", "State-of-the-art plant in Sanford, NC", "Marine Class Approval of Manufacturer"], "facts_used": ["Founded in 2020 -> db", "Headquarters in Sanford, North Carolina -> db", "Produces lightweight aluminum parts and steel parts -> /", "Serves automotive (trucks, cars), off-highway, and marine industries -> /, /about-us", "Holds ISO 14001 certification -> db", "Holds Marine Class Approval of Manufacturer -> /about-us", "Claims lowest total cost of ownership -> /", "Reducing carbon footprint while expanding -> /", "State-of-the-art plant in Sanford, NC -> /", "Backed by an international network -> /", "Community involvement with Salvation Army, Downtown Sanford, Habitat for Humanity -> /about-us", "Education partnerships with NC State and Lee County School System -> /about-us", "Employee tuition reimbursement -> /about-us", "Growth plan: 2X in 2 years, 3X in 5 years -> /"], "company_type": "Manufacturer", "makes_products": "yes", "type_evidence": "Now Creating Lightweight Aluminum Parts At Our State-of-the-Art Plant In Sanford, NC", "founded_year": "2020", "employee_count": "", 